package com.aoo.bcg.common.cache;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.security.NoSuchAlgorithmException;
/** Stable load spread for club members, popular game catalogs and room-route indexes. */
public final class CacheShardRouter{private final int shardCount;public CacheShardRouter(int shardCount){if(shardCount<2||shardCount>1024||Integer.bitCount(shardCount)!=1)throw new IllegalArgumentException("shardCount must be a power of two");this.shardCount=shardCount;}public int shard(String identifier){try{byte[]digest=MessageDigest.getInstance("SHA-256").digest(identifier.getBytes(StandardCharsets.UTF_8));int hash=((digest[0]&255)<<24)|((digest[1]&255)<<16)|((digest[2]&255)<<8)|(digest[3]&255);return hash&(shardCount-1);}catch(NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}public String key(CacheKey key){return key.shardedValue(shard(key.id()));}public int shardCount(){return shardCount;}}
